const input = $input.first().json;
const required = ['campaign_name', 'target_country', 'active_products_csv'];
const missing = required.filter((key) => !String(input[key] ?? '').trim());
if (missing.length) throw new Error(`Missing required campaign fields: ${missing.join(', ')}`);
const products = String(input.active_products_csv)
  .split(/[\n,;|]+/).map((v) => v.trim().toLowerCase()).filter(Boolean)
  .filter((v, i, a) => a.indexOf(v) === i);
if (!products.length) throw new Error('At least one active product is required.');
const targetLeads = Math.max(1, Math.min(5000, Math.round(Number(input.target_leads || 100))));
const maxCost = Math.max(0, Number(input.maximum_cost_per_contactable_lead_usd || 0.5));
const slug = String(input.campaign_name).toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '').slice(0, 60);
const warnings = [];
if (Number(input.target_leads) !== targetLeads) warnings.push('target_leads was normalized into the range 1–5000.');
if (input.automatic_sending === true) warnings.push('automatic_sending was forced to false for V1 safety.');
return [{json:{campaign:{
  campaign_key:`${slug || 'campaign'}-${new Date().toISOString().slice(0,10)}`,
  campaign_name:String(input.campaign_name).trim(), target_country:String(input.target_country).trim(),
  buyer_scope:String(input.buyer_scope || '').trim(), active_products:products, target_leads:targetLeads,
  maximum_cost_per_contactable_lead_usd:maxCost, minimum_order:String(input.minimum_order || '1 container').trim(),
  include_phone_only_buyers:input.include_phone_only_buyers !== false,
  include_wechat_first_buyers:input.include_wechat_first_buyers !== false,
  automatic_sending:false, source_strategy:String(input.source_strategy || 'public-first'),
  workflow_version:String(input.workflow_version || '1.0.0'), created_at:new Date().toISOString()
},validation:{valid:true,warnings}}}];

const data = $input.first().json; const campaign = data.campaign;
const buyerSegments = [
 {key:'importer',label_en:'seafood importer',label_zh:'海鲜进口商'},
 {key:'processor',label_en:'seafood processor',label_zh:'水产加工企业'},
 {key:'distributor',label_en:'seafood distributor',label_zh:'海鲜经销商'},
 {key:'wholesaler',label_en:'seafood wholesaler',label_zh:'海鲜批发商'},
 {key:'trading_company',label_en:'seafood trading company',label_zh:'水产贸易公司'},
 {key:'cold_storage',label_en:'cold storage seafood buyer',label_zh:'水产冷库采购商'},
 {key:'food_service_supplier',label_en:'food service seafood supplier',label_zh:'餐饮海鲜供应商'},
 {key:'regional_trader',label_en:'regional seafood trader',label_zh:'区域水产贸易商'}
];
const productZh = {'horse mackerel':'竹荚鱼','sardine':'沙丁鱼','sardines':'沙丁鱼','shrimp':'虾','mackerel':'鲭鱼','indian mackerel':'印度鲭鱼','ribbonfish':'带鱼','hairtail':'带鱼','grouper':'石斑鱼','kingfish':'马鲛鱼','queenfish':'女王鱼','emperor fish':'皇帝鱼'};
const cities=['Qingdao','Dalian','Guangzhou','Xiamen']; const cityZh=['青岛','大连','广州','厦门'];
const queries=[];
for (const product of campaign.active_products) {
 const zh=productZh[product] || product;
 queries.push(`${product} seafood importer China`,`${product} frozen fish wholesaler China`,`${product} seafood processor ${cities.join(' OR ')}`,`${product} seafood trading company China`,`${zh} 进口商 中国`,`${zh} 批发商 中国`,`${zh} 水产加工 ${cityZh.join(' OR ')}`,`${zh} 水产贸易公司 中国`);
}
const uniqueQueries=[...new Set(queries)].slice(0,80);
return [{json:{...data,icp:{target_country:campaign.target_country,buyer_segments:buyerSegments,digital_presence_rule:'Weak or missing website is not a rejection reason.',commercial_rule:`Minimum order starts from ${campaign.minimum_order}.`,reject_only_when:['clearly unrelated to seafood','consumer-only','invalid or nonexistent','duplicate','fraudulent or suspicious','not commercially capable']},search_plan:{query_count:uniqueQueries.length,queries:uniqueQueries,priority_cities:cities,priority_cities_zh:cityZh,source_order:['existing_neon_database','public_search_results','official_company_websites','seafood_exhibitor_lists','industry_associations','public_trade_directories','b2b_marketplaces','apify_after_public_sources','apollo_only_after_relevance_is_proven']}}}];

const data=$input.first().json; const c=data.campaign;
const maxBudget=Number((c.target_leads*c.maximum_cost_per_contactable_lead_usd).toFixed(2));
return [{json:{...data,cost_control:{target_metric:'cost_per_contactable_lead',max_cost_per_contactable_lead_usd:c.maximum_cost_per_contactable_lead_usd,maximum_theoretical_campaign_lead_budget_usd:maxBudget,provider_waterfall:[
 {step:1,provider:'existing_database',paid:false},{step:2,provider:'source_page',paid:false},{step:3,provider:'official_website',paid:false},{step:4,provider:'public_directory',paid:false},{step:5,provider:'apify',paid:true,condition:'public extraction is insufficient'},{step:6,provider:'apollo',paid:true,condition:'buyer relevance is supported and no usable contact exists'},{step:7,provider:'prospeo',paid:true,condition:'Apollo/public channels failed'},{step:8,provider:'email_verifier',paid:true,condition:'an email candidate exists'}],stop_rules:['Stop paid enrichment when a usable business contact exists.','Do not call Apollo before buyer relevance is supported.','Cache provider responses in Neon.','Hash source content and skip unchanged pages.','Use deterministic code before LLM calls.']},safety:{automatic_sending:false,outreach_status:'disabled_until_mailbox_and_controls_are_ready',human_approval_required_for:['outreach activation','quotation','commercial commitment']}}}];
